DROP TABLE IF EXISTS `book`;
CREATE TABLE `book` (
  `book_id` int(11) NOT NULL AUTO_INCREMENT,
  `call_number` varchar(50) NOT NULL,
  `accession_number` varchar(50) NOT NULL,
  `title` varchar(255) NOT NULL,
