  `author` varchar(255) NOT NULL,
  `copyright_date` varchar(20) NOT NULL,
  `publisher` varchar(50) NOT NULL,
  `place_publication` varchar(50) NOT NULL,
  `isbn` varchar(50) NOT NULL,
  `barcode` varchar(50) NOT NULL,
  `book_image` varchar(100) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `subject1` varchar(255) NOT NULL,
  `subject2` varchar(255) NOT NULL,
  `date_added` datetime NOT NULL,
  `status` varchar(50) NOT NULL,
  `status_hold` varchar(50) NOT NULL,
  `page` varchar(255) NOT NULL,
  `price` varchar(255) NOT NULL,
  PRIMARY KEY (`book_id`),
  KEY `category_id` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `borrow_book`;
