  PRIMARY KEY (`borrow_book_id`),
  KEY `user_id` (`user_id`),
  KEY `faculty_id` (`faculty_id`),
  KEY `borrow_book_ibfk_1` (`book_id`),
  CONSTRAINT `borrow_book_ibfk_1` FOREIGN KEY (`book_id`) REFERENCES `book` (`book_id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=861 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;



